insert into g_real values (1, '00000000-0000-4000-9000-000000000501', 'length', 824, '{"about_course": true, "sentences": [{"text": "The Bachelor of Arts gives you the freedom to explore what matters to you while building the skills to create meaningful change in communities, workplaces and society.", "quote": "The Bachelor of Arts gives you the freedom to explore what matters to you while building the skills to create meaningful change in communities, workplaces and society.", "on_page": true}, {"text": "Choosing from a wide range of majors, including history, creative writing, sociology and more, you''ll develop a deeper understanding of people, policy and cultures while preparing for a wide range of careers.", "quote": "Choosing from a wide range of majors, including history, creative writing, sociology and more, you''ll develop a deeper understanding of people, policy and cultures while preparing for a wide range of careers.", "on_page": true}, {"text": "The Bachelor of Arts is built around a connected core journey designed to support you throughout your degree, combining your interests with practical experience, industry engagement and career-focused learning.", "quote": "More than a collection of subjects, our Bachelor of Arts is built around a connected core journey designed to support you throughout your degree. You''ll combine your interests with practical experience, industry engagement and career-focused learning, graduating with the confidence, adaptability and purpose to succeed in your chosen field.", "on_page": true}, {"text": "You can choose from a broad range of majors and electives, explore social, cultural, political and environmental challenges, and gain practical workplace experience through one of the largest range of industry internships in Queensland.", "quote": "Choose from a broad range of majors, encompassing history, literary studies, creative writing, sociology and much more, combined with electives and flexible study options to create a degree aligned with your interests and ambitions. Explore social, cultural, political and environmental challenges while learning how to contribute meaningful solutions. With one of the largest range of industry internships in Queensland, you''ll gain practical workplace experience and connect directly with employers.", "on_page": true}]}'::jsonb);
