insert into g_real values (2, '00000000-0000-4000-9000-000000000502', 'length', 760, '{"about_course": true, "sentences": [{"text": "The Diploma of Business Studies will equip you with foundational knowledge, practical skills, and future-ready capabilities to thrive in today’s fast-changing business environment.", "quote": "The Diploma of Business Studies will equip you with foundational knowledge, practical skills, and future-ready capabilities to thrive in today’s fast-changing business environment.", "on_page": true}, {"text": "You will build essential competencies in areas such as accounting, business analytics, economics, management, marketing, and business law, while also having the opportunity to explore fields like human resource management, property, or financial planning.", "quote": "You will build essential competencies in areas such as accounting, business analytics, economics, management, marketing, and business law, while also having the opportunity to explore fields like human resource management, property, or financial planning.", "on_page": true}, {"text": "With flexible online and part-time study options, this course supports you to balance your learning with work and life commitments.", "quote": "With flexible online and part-time study options, this course supports you to balance your learning with work and life commitments.", "on_page": true}, {"text": "Upon successful completion, you’ll be eligible for credit for up to eight units in CQUniversity’s Bachelor of Business, allowing you to transition directly into the second year of the degree.", "quote": "Upon successful completion, you’ll be eligible for credit for up to eight units in CQUniversity’s Bachelor of Business , allowing you to transition directly into the second year of the degree.", "on_page": true}]}'::jsonb);
