insert into g_real values (4, '00000000-0000-4000-9000-000000000504', 'sentence_count', 860, '{"about_course": true, "sentences": [{"text": "The Bachelor of Midwifery prepares you for entry to professional midwifery practice.", "quote": "The Bachelor of Midwifery prepares you for entry to professional midwifery practice.", "on_page": true}, {"text": "You will develop the skills and knowledge necessary to provide quality, woman-centred care through safe and effective midwifery practice in accordance with the Australian Nursing and Midwifery Accreditation Council standards for practice.", "quote": "You will develop the skills and knowledge necessary to provide quality, woman-centred care through safe and effective midwifery practice in accordance with the Australian Nursing and Midwifery Accreditation Council standards for practice.", "on_page": true}, {"text": "Study areas include anatomy and physiology, midwifery theory and practice, primary healthcare, perinatal mental health, care during preconception, pregnancy, labour and birth, and early parenting.", "quote": "Study areas include anatomy and physiology, midwifery theory and practice, primary healthcare, perinatal mental health, care during preconception, pregnancy, labour and birth, and early parenting.", "on_page": true}, {"text": "Graduates will be equipped to work in multi-disciplinary teams and in partnership with women to contribute to healthier outcomes for mother and baby.", "quote": "Graduates will be equipped to work in multi-disciplinary teams and in partnership with women to contribute to healthier outcomes for mother and baby.", "on_page": true}, {"text": "Graduates of this degree will be eligible for registration with the Australian Health Practitioner Regulation Agency (AHPRA) and practice as a Registered Midwife across a range of settings.", "quote": "Graduates of this degree will be eligible for registration with the Australian Health Practitioner Regulation Agency (AHPRA) and practice as a Registered Midwife across a range of settings.", "on_page": true}]}'::jsonb);
