insert into g_real values (5, '00000000-0000-4000-9000-000000000505', 'sentence_count', 739, '{"about_course": true, "sentences": [{"text": "The MBA Global will prepare you for leadership roles in Australia and beyond.", "quote": "Taught by industry experts from around the world, the MBA Global will prepare you for leadership roles in Australia and beyond.", "on_page": true}, {"text": "This program will develop your international business leadership and management skills.", "quote": "This program will develop your international business leadership and management skills.", "on_page": true}, {"text": "The core courses aim to build your skills to deliver sophisticated strategies in a variety of contexts.", "quote": "The core courses aim to build your skills to deliver sophisticated strategies in a variety of contexts.", "on_page": true}, {"text": "You will gain an understanding of the international ''big picture'', to make you an asset to employers, or a business leader.", "quote": "You will gain an understanding of the international ''big picture'', to make you an asset to employers, or a business leader.", "on_page": true}, {"text": "This course will hone practical skills in Leading and Managing People, Macroeconomics for Managers, Global Strategy, and Marketing Management.", "quote": "This course will hone practical skills in: Leading and Managing People Macroeconomics for Managers Global Strategy Marketing Management.", "on_page": true}, {"text": "The MBA (Global) is designed for individuals who are recent graduates in any discipline, who have limited work experience, and who are looking to develop their business leadership and management skills.", "quote": "The MBA (Global) is designed for individuals who are recent graduates in any discipline, who have limited work experience, and who are looking to develop their business leadership and management skills.", "on_page": true}]}'::jsonb);
