insert into g_real values (6, '00000000-0000-4000-9000-000000000506', 'sentence_count', 1054, '{"about_course": true, "sentences": [{"text": "Step into a rewarding career as a pharmacist, where science meets patient care.", "quote": "Step into a rewarding career as a pharmacist, where science meets patient care.", "on_page": true}, {"text": "Explore how medicines are developed and used to improve health, gain hands-on clinical experience and prepare to make a real impact in pharmaceutical, biotechnology and nutraceutical industries.", "quote": "Explore how medicines are developed and used to improve health, gain hands-on clinical experience and prepare to make a real impact in pharmaceutical, biotechnology and nutraceutical industries.", "on_page": true}, {"text": "Take specialist courses in areas such as pharmacy management, complementary and alternative medicine and pharmacology.", "quote": "Take specialist courses in areas such as pharmacy management, complementary and alternative medicine and pharmacology.", "on_page": true}, {"text": "Expand your knowledge and skills during 150 hours of professional practice placements in clinical settings like the Gold Coast University Hospital, including the opportunity for rural and international placements.", "quote": "Expand your knowledge and skills during 150 hours of professional practice placements in clinical settings like the Gold Coast University Hospital, including the opportunity for rural and international placements.", "on_page": true}, {"text": "You''ll learn with students from different health fields to ensure you''re ready to work in healthcare teams after you graduate.", "quote": "We know the best outcomes for patients and health professionals come from close collaboration, so you''ll learn with students from different health fields to ensure you''re ready to work in healthcare teams after you graduate.", "on_page": true}, {"text": "Train in cutting-edge labs that bring learning to life including an immersive virtual pharmacy, real dispensary, and specialised labs in formulation, pharmacology and analysis.", "quote": "Train in cutting-edge labs that bring learning to life. Explore our immersive virtual pharmacy, real dispensary, and specialised labs in formulation, pharmacology and analysis, designed to provide next-level practical experience.", "on_page": true}, {"text": "With this honours degree, you''ll gain advanced research skills that open doors to postgraduate study and strengthen your employment prospects.", "quote": "With this honours degree, you''ll gain advanced research skills that open doors to postgraduate study. Strengthen your employment prospects with the ability to conduct research, evaluate outcomes and apply evidence-based practice across a range of professional settings.", "on_page": true}]}'::jsonb);
