insert into g_real values (7, '00000000-0000-4000-9000-000000000507', 'unsupported_claim', 459, '{"about_course": true, "sentences": [{"text": "The Bachelor of Secondary Education prepares students for a career as a secondary school teacher with the flexibility to teach from Year 7 through to VCE.", "quote": "Prepare for a rewarding career as a secondary school teacher with the flexibility to teach from Year 7 through to VCE.", "on_page": true}, {"text": "Students gain deep knowledge of two specialist teaching areas combined with valuable classroom experience, including a minimum of 80 days of supervised teaching placement.", "quote": "Our Bachelor of Secondary Education will see you gain a deep knowledge of two specialist teaching areas combined with valuable classroom experience. You will graduate with the confidence to connect with young people and teach from year 7 through to VCE. ... You''ll be ready to teach by undertaking a minimum of 80 days of supervised teaching placement with our partner schools throughout the course.", "on_page": false}, {"text": "The course is structured over four years full-time or part-time equivalent, with study on campus at Berwick, Gippsland, or Mt Helen.", "quote": "Duration 4 years full-time or part-time equivalent ... Locations Berwick (on campus) Gippsland (on campus) Mt Helen (on campus)", "on_page": false}]}'::jsonb);
