insert into g_real values (8, '00000000-0000-4000-9000-000000000508', 'unsupported_claim', 803, '{"about_course": true, "sentences": [{"text": "This research degree encompasses the disciplines of Biomedical Sciences, Exercise, Sport and Rehabilitation Science, Clinical Sciences, Medical Radiation Science, Pharmaceutical Sciences, and Psychology and Behavioural Science.", "quote": "This research degree encompasses the disciplines of Biomedical Sciences, Exercise, Sport and Rehabilitation Science, Clinical Sciences, Medical Radiation Science, Pharmaceutical Sciences, and Psychology and Behavioural Science.", "on_page": true}, {"text": "Students learn to demonstrate mastery of theoretical knowledge and to reflect critically on that knowledge and its application.", "quote": "demonstrate mastery of theoretical knowledge and to reflect critically on that knowledge and its application", "on_page": true}, {"text": "They investigate, analyse and synthesise complex information, problems, concepts and theories and apply established theories to different bodies of knowledge or practice.", "quote": "investigate, analyse and synthesise complex information, problems, concepts and theories and apply established theories to different bodies of knowledge or practice", "on_page": true}, {"text": "The course develops skills to design, use and evaluate research and research methods and to present a coherent and sustained argument and to disseminate research concepts, plans and results to the general community, peers and the national and international research community.", "quote": "design, use and evaluate research and research methods present a coherent and sustained argument and to disseminate research concepts, plans and results to the general community, peers and the national and international research community", "on_page": true}]}'::jsonb);
