insert into g_real values (9, '00000000-0000-4000-9000-000000000509', 'unsupported_claim', 724, '{"about_course": true, "sentences": [{"text": "The Bachelor of Education (Early Childhood and Primary) qualifies you to teach children from birth to 12 years of age in childcare, kindergartens, preschools, and primary school settings.", "quote": "The Bachelor of Education (Early Childhood and Primary) qualifies you to teach children from birth to 12 years of age in childcare, kindergartens, preschools, and primary school settings.", "on_page": true}, {"text": "The degree is dual-accredited and equips students with pedagogical knowledge and experiential skills to inspire and support children in developing lifelong learning abilities.", "quote": "Focused on developing children’s foundation and early learning needs, our dual-accredited degree will equip you with the pedagogical knowledge and experiential skills to inspire and support children in developing lifelong learning abilities.", "on_page": true}, {"text": "Students learn to engage children in exploring their creative, physical, and cognitive capabilities within inclusive environments that encourage and nurture diversity.", "quote": "You will learn how to engage children in exploring their creative, physical, and cognitive capabilities within inclusive environments that encourage and nurture diversity.", "on_page": true}, {"text": "The course includes specialised teaching areas such as literacy, numeracy, or religious education and professional experience placements in both early childhood and primary education settings.", "quote": "Hone your knowledge and build a solid foundation with a specialised teaching area from literacy, numeracy, or religious education and your professional experience placements will be conducted in both early childhood and primary education settings.", "on_page": true}]}'::jsonb);
