-- Guards: Platform Admin direction 6 Nov 2026 08:12 (course descriptions: safe parallel planning and independent validation).
-- Real held readings from production (pipeline.field_enrich_items, field description, state skipped, created from 5 Nov 2026), read only
-- fxcwkweaxjtknorudmwp, 6 Nov 2026 08:56 AEDT, first 3 per rule by id. Public course-page sentences and their page quotes only: no ids,
-- no provider or course names, no user data. Each case gets a fresh provider and course, so the outcome depends only on the reading,
-- the settings and the live check; it must equal the rule production recorded.
\set ON_ERROR_STOP 1
create temporary table g_real(n int primary key, course uuid, expect text, recorded_chars int, result jsonb);
update g_real set result = security.course_description_check_v1(course, result) where true;
do $$ declare c record; v_bad int := 0; begin
  for c in select * from g_real order by n loop
    raise notice 'real % [%] recorded % got % (chars recorded %, now %)', c.n, case when c.result->>'rule' = c.expect then 'pass' else 'FAIL' end,
      c.expect, c.result->>'rule', c.recorded_chars, c.result->'checks'->>'chars';
    if c.result->>'rule' is distinct from c.expect or (c.result->'checks'->>'chars')::int is distinct from c.recorded_chars then v_bad := v_bad + 1; end if;
  end loop;
  if v_bad > 0 then raise exception '% real held reading(s) no longer get the rule production recorded', v_bad; end if;
end $$;
